head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면이 최초 로드될때 실행되는 초기화 이벤트 — 화면 초기화(init)를 수행한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
    try {
        scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00311.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면이 종료될때 발생하는 이벤트(현재 처리 없음)
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageunload 바인딩으로 자동 호출)
 */
scwin.onpageunload = function() {
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name init
 * @description 화면 초기화
 * @returns {void}
 * @hidden N
 * @example scwin.init();
 */
scwin.init = function() {
    scwin.search();
};

/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 * @example scwin.initDs();
 */
scwin.initDs = function() {
    dlt_ContgntDebtRes.removeAll();
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {Boolean} 조회조건이 유효하면 true
 * @hidden N
 * @example if (!scwin.chkValid()) { return; }
 */
scwin.chkValid = function() {

    const ibxKisCd = $p.parent().wfm_header.getWindow().ibx_KisCd.getValue();
    const sbxAcntclsDt = $p.parent().wfm_header.getWindow().sbx_AcntclsDt.getValue();

    if (ibxKisCd === "" || sbxAcntclsDt === "") {
        return false;
    }
    return true;
};

/**
 * @method
 * @name search
 * @description 우발채무  조회
 * @returns {void}
 * @hidden N
 * @example await scwin.search();
 */
scwin.search = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!scwin.chkValid()) {
        return;
    }

    const ibxKisCd = $p.parent().wfm_header.getWindow().ibx_KisCd.getValue();
    const sbxAcntclsDt = $p.parent().wfm_header.getWindow().sbx_AcntclsDt.getValue();

    const url = "/api/listing/nice/individual-notes/contingent-liabilities?kisCd="+ibxKisCd+"&acntclsDt="+sbxAcntclsDt;
    await $c.sbm.setAction(sbm_dlt_ContgntDebt, url);
    await $c.sbm.execute(sbm_dlt_ContgntDebt);

    await scwin.appendContents();
};

/**
 * @method
 * @name appendContents
 * @description 컨텐츠 append
 * @returns {void}
 * @hidden N
 * @example scwin.appendContents();
 */
scwin.appendContents = function() {
    let strContent = "<div style='overflow-x:hidden;overflow-y:scroll;width:100%;height:600px;font-family:돋움체;'>";
    for (let nRow = 0; nRow <= dlt_ContgntDebtRes.getRowCount(); nRow++) {
        strContent = strContent + dlt_ContgntDebtRes.getCellData(nRow, "ctnt");
    }
    strContent = strContent + "</div>";
    const grpCtntObj = $p.getComponentById("grp_Ctnt").render;
    grpCtntObj.innerHTML = strContent;
    grp_Ctnt.setStyle("border", "1px solid blue");
    grp_Ctnt.setStyle("magin-top", "30px");
};

/**
 * @method
 * @name gform_onload
 * @description gform 로드 이벤트(레거시 호환) — 화면 초기화(init)를 수행한다.
 * @returns {void}
 * @hidden N
 * @example scwin.gform_onload();
 */
scwin.gform_onload = function() {
    scwin.init();
};
